  AND job_position_id = #{jobPositionId}

mapper.update:
UPDATE job_match
SET match_result    = #{matchResult},
    reference_date  = #{referenceDate},
    import_file_id  = #{importFileId},
    updated_at      = #{updatedAt}
WHERE id = #{id}

mapper.delete:
DELETE FROM job_match_item
WHERE job_match_id IN (
    SELECT id FROM job_match WHERE import_file_id = #{importFileId}
)

mapper.sql:
WHERE m.profile_id = #{profileId}

    AND m.import_file_id = #{importFileId}


    AND m.match_result = #{matchResult}

mapper.select:
SELECT match_result AS matchResult, COUNT(*) AS cnt
FROM job_match
WHERE profile_id = #{profileId}
  AND import_file_id = #{importFileId}
GROUP BY match_result
